package com.fabrizioroot.vertal.controller;
import com.fabrizioroot.vertal.dto.*; import com.fabrizioroot.vertal.service.TaskService; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/tasks") public class TaskController { private final TaskService tasks; public TaskController(TaskService t){tasks=t;}
 @PostMapping public TaskResponseDto create(@AuthenticationPrincipal Long uid,@Valid @RequestBody TaskRequestDto dto){return tasks.create(uid,dto);} @GetMapping public List<TaskResponseDto> list(@AuthenticationPrincipal Long uid){return tasks.list(uid);} @GetMapping("/{id}") public TaskResponseDto get(@AuthenticationPrincipal Long uid,@PathVariable Long id){return tasks.get(uid,id);} @PutMapping("/{id}") public TaskResponseDto update(@AuthenticationPrincipal Long uid,@PathVariable Long id,@Valid @RequestBody TaskRequestDto dto){return tasks.update(uid,id,dto);} @DeleteMapping("/{id}") public void delete(@AuthenticationPrincipal Long uid,@PathVariable Long id){tasks.delete(uid,id);} @PostMapping("/{id}/assignments") public void assign(@AuthenticationPrincipal Long uid,@PathVariable Long id,@Valid @RequestBody AssignmentRequestDto dto){tasks.assign(uid,id,dto);} @PutMapping("/{id}/status") public TaskResponseDto status(@AuthenticationPrincipal Long uid,@PathVariable Long id,@Valid @RequestBody StatusUpdateRequestDto dto){return tasks.status(uid,id,dto);} @PutMapping("/{id}/complete") public TaskResponseDto complete(@AuthenticationPrincipal Long uid,@PathVariable Long id){return tasks.complete(uid,id);} @PostMapping("/{id}/reminders") public ReminderResponseDto reminder(@AuthenticationPrincipal Long uid,@PathVariable Long id,@Valid @RequestBody ReminderRequestDto dto){return tasks.reminder(uid,id,dto);} @GetMapping("/{id}/reminders") public List<ReminderResponseDto> reminders(@AuthenticationPrincipal Long uid,@PathVariable Long id){return tasks.reminders(uid,id);}
}